import{_ as o,o as t,c as a,a8 as d}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"Cross-version Upgrades","description":"","frontmatter":{"title":"Cross-version Upgrades","lang":"en"},"headers":[],"relativePath":"advance/upgrade.md","filePath":"advance/upgrade.md","lastUpdated":1790354326000}'),c={name:"advance/upgrade.md"};function i(r,e,l,n,h,s){return t(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJDcm9zcy12ZXJzaW9uJTIwVXBncmFkZXMlMjIlMkMlMjJsYW5nJTIyJTNBJTIyZW4lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1NDMyNjAwMCU3RA=="},[...e[0]||(e[0]=[d('<h1 id="cross-version-upgrades" tabindex="-1">Cross-version Upgrades <a class="header-anchor" href="#cross-version-upgrades" aria-label="Permalink to &quot;Cross-version Upgrades&quot;">​</a></h1><p>To upgrade the module, you need to reinstall it according to the instructions in <a href="/ngx_waf-docs/guide/installation.html">installation guide</a>.</p><h2 id="upgrade-from-9-x-x-to-10-x-x" tabindex="-1">Upgrade from <code>9.x.x</code> to <code>10.x.x</code> <a class="header-anchor" href="#upgrade-from-9-x-x-to-10-x-x" aria-label="Permalink to &quot;Upgrade from `9.x.x` to `10.x.x`&quot;">​</a></h2><ol><li>If you use the directive <code>waf_http_status</code>, replace it with the directive <code>waf_action</code> according to the documentation.</li><li>If you set the parameter <code>size</code> of the directive <code>waf_cc_deny</code>, you should replace it with the parameter <code>zone</code> according to the documentation.</li><li>If you use the parameter <code>CAPTCHA</code> of the directive <code>waf_cc_deny</code>, you should use the directive <code>waf_action</code> instead, according to the documentation.</li></ol><h2 id="upgrade-from-8-x-x-to-9-x-x" tabindex="-1">Upgrade from <code>8.x.x</code> to <code>9.x.x</code> <a class="header-anchor" href="#upgrade-from-8-x-x-to-9-x-x" aria-label="Permalink to &quot;Upgrade from `8.x.x` to `9.x.x`&quot;">​</a></h2><ol><li>Install the dynamic libraries and headers for <a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">libmodsecurity</a>.</li><li>Run the command <code>git clone -b v2.3.0 https://github.com/troydhanson/uthash.git lib/uthash</code> in the root of the project.</li><li>Remove some parameters from the command <code>waf_mode</code>, if you are using them. <ul><li>LIBINJECTION</li><li>LIBINJECTION-SQLI</li><li>LIBINJECTION-XSS</li><li>ADV</li></ul></li><li>Delete the file <code>advanced</code> for advanced rules. 5.</li><li>The parameter <code>ADV</code> of the directive <code>waf_priority</code> is removed, please delete it if you use this parameter.</li><li>A new parameter <code>MODSECURITY</code> has been added to the directive <code>waf_priority</code>. If you use this directive, please fill in the parameter in the appropriate place.</li></ol><h2 id="upgrade-from-7-x-x-to-8-x-x" tabindex="-1">Upgrade from <code>7.x.x</code> to <code>8.x.x</code> <a class="header-anchor" href="#upgrade-from-7-x-x-to-8-x-x" aria-label="Permalink to &quot;Upgrade from `7.x.x` to `8.x.x`&quot;">​</a></h2><ol><li>Install the dynamic libraries and headers for <code>libcurl</code>.</li><li>Run the command <code>git clone https://github.com/DaveGamble/cJSON.git lib/cjson</code> in the root of the project.</li><li>Run the command <code>git clone https://github.com/libinjection/libinjection.git lib/libinjection</code> at the root of the project.</li><li>If you used the directive <code>waf_mode</code> and used the directive&#39;s parameters <code>CC</code> or <code>CACHE</code>, remove both parameters. The function of each of these two parameters has been moved into the directive <code>waf_cc_deny</code> and <code>waf_cache</code> respectively.</li><li>If you want to enable CC protection, change the parameter of the directive <code>waf_cc_deny</code>, for example, change <code>waf_cc_deny rate=2000r/m duration=1h</code> to <code>waf_cc_deny on rate=2000r/m duration=1h</code>.</li><li>If you want to enable caching, change the parameter of the directive <code>waf_cache</code>, for example, change <code>waf_cache capacity=50</code> to <code>waf_cache on capacity=50</code>.</li><li>If you use the directives <code>waf_cc_deny</code> or <code>waf_cache</code> in the <code>http</code> context, move these two directives to a lower context, such as to the <code>server</code> context.</li><li>If you use the directive <code>waf_cache</code> and use the directive&#39;s parameters <code>interval</code> or <code>percent</code>, remove these two parameters, which have been removed.</li><li>If you use the directive <code>waf_priority</code>, add <code>VERIFY-BOT</code> and <code>CAPTCHA</code> to it.</li></ol><h2 id="upgrade-from-6-x-x-to-7-x-x" tabindex="-1">Upgrade from <code>6.x.x</code> to <code>7.x.x</code> <a class="header-anchor" href="#upgrade-from-6-x-x-to-7-x-x" aria-label="Permalink to &quot;Upgrade from `6.x.x` to `7.x.x`&quot;">​</a></h2><ol><li>If you use the directive <code>waf_cc_deny</code> in the <code>http</code> block, move this directive to a more internal level.</li></ol><h2 id="upgrade-from-5-x-x-to-6-x-x" tabindex="-1">Upgrade from <code>5.x.x</code> to <code>6.x.x</code> <a class="header-anchor" href="#upgrade-from-5-x-x-to-6-x-x" aria-label="Permalink to &quot;Upgrade from `5.x.x` to `6.x.x`&quot;">​</a></h2><ol><li>Create a new empty file named <code>advanced</code> in the rules directory.</li><li>If the directive <code>waf_priority</code> is used, you can delete it or modify it according to the directive in the documentation.</li></ol>',12)])])}const m=o(c,[["render",i]]);export{u as __pageData,m as default};
